73	// 3. A status other than 200 is a *oci.StatusError from the management API,
74	// carrying the code and nothing else: no status line, no body, no credential.
75	func TestNexusStatusIsATypedManagementAPIError(t *testing.T) {
76		const bodyMarker = "BODY-MARKER-FROM-THE-SERVER"
77		for _, status := range []int{
78			http.StatusUnauthorized,        // 401
79			http.StatusForbidden,           // 403
80			http.StatusNotFound,            // 404
81			http.StatusTooManyRequests,     // 429
82			http.StatusInternalServerError, // 500
83			http.StatusBadGateway,          // 502
84			http.StatusServiceUnavailable,  // 503
85		} {
86			t.Run(fmt.Sprintf("%d", status), func(t *testing.T) {
87				info, hits := nexusServer(t, func(w http.ResponseWriter, _ *http.Request) {
88					w.WriteHeader(status)
89					_, _ = io.WriteString(w, bodyMarker)
90				})
91	
92				members, err := (&NexusDetector{}).DetectGroup(context.Background(), info)
93	
94				if len(members) != 0 {
95					t.Errorf("members = %v, want none", members)
96				}
97				if err == nil {
98					t.Fatal("err = nil, want a status error")
99				}
100				var se *oci.StatusError
101				if !errors.As(err, &se) {
102					t.Fatalf("err = %v (%T), want errors.As *oci.StatusError", err, err)
103				}
104				if se.Code != status {
105					t.Errorf("StatusError.Code = %d, want %d", se.Code, status)
106				}
107				if se.Source != oci.SourceManagementAPI {
108					t.Errorf("StatusError.Source = %v, want oci.SourceManagementAPI", se.Source)
109				}
110				if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
111					t.Errorf("err = %v, a status error is not a context error", err)
112				}
113				msg := err.Error()
114				wantNoSecret(t, "error", msg)
115				for _, leak := range []string{nexusTestUser, bodyMarker, http.StatusText(status)} {
116					if strings.Contains(msg, leak) {
117						t.Errorf("error leaks %q: %s", leak, msg)
118					}
119				}
120				if !strings.Contains(msg, fmt.Sprintf("%d", status)) {
121					t.Errorf("error = %q, want the status code in it", msg)
122				}
123				if got := hits.Load(); got != 1 {
124					t.Errorf("the server received %d requests, want 1 (the generic endpoint only)", got)
125				}
126			})
127		}
128	}
