196	// 4. A cancellation that arrives while the body is being read is a context
197	// error, whatever net/http makes of a body cut short.
198	func TestNexusCancelDuringTheBodyIsAContextError(t *testing.T) {
199		started := make(chan struct{}, 1)
200		info, _ := nexusServer(t, func(w http.ResponseWriter, r *http.Request) {
201			// Promise more than is sent: the headers and 10 bytes, then silence.
202			w.Header().Set("Content-Length", "1000")
203			w.WriteHeader(http.StatusOK)
204			_, _ = io.WriteString(w, `{"type":"g`)
205			w.(http.Flusher).Flush()
206			select {
207			case started <- struct{}{}:
208			default:
209			}
210			blockUntilGone(t, r)
211		})
212		ctx, cancel := context.WithCancel(context.Background())
213		defer cancel()
214		go func() {
215			select {
216			case <-started:
217				cancel()
218			case <-time.After(5 * time.Second):
219				cancel() // the server never answered: let the call fail rather than hang
220			}
221		}()
222	
223		members, err := (&NexusDetector{}).DetectGroup(ctx, info)
224	
225		wantContextError(t, err, context.Canceled)
226		if len(members) != 0 {
227			t.Errorf("members = %v, want none", members)
228		}
229	}
