290	// 6. The format endpoint keeps swallowing its errors (NX-07): an unreadable
291	// reply there only means no members, and the detection does not fail or panic.
292	func TestNexusUnreadableFormatReplyGivesNoMembers(t *testing.T) {
293		for _, body := range []string{"", "  \n", "{", "<html>login</html>", "null", `{"group":{"memberNames":5}}`} {
294			t.Run(fmt.Sprintf("%q", body), func(t *testing.T) {
295				var formatHits atomic.Int32
296				info, _ := nexusServer(t, func(w http.ResponseWriter, r *http.Request) {
297					if strings.Contains(r.URL.Path, "/group/") {
298						formatHits.Add(1)
299						_, _ = io.WriteString(w, body)
300						return
301					}
302					_, _ = io.WriteString(w, nexusGroupNoMembers)
303				})
304	
305				members, err := (&NexusDetector{}).DetectGroup(context.Background(), info)
306	
307				if err != nil {
308					t.Errorf("err = %v, want nil (the format endpoint's errors are swallowed)", err)
309				}
310				if len(members) != 0 {
311					t.Errorf("members = %v, want none", members)
312				}
313				if got := formatHits.Load(); got < 1 {
314					t.Errorf("the format endpoint was never asked, the test checks nothing")
315				}
316			})
317		}
318	}
319	
320	// 5. A repository that Nexus describes and that is not a group is a settled
321	// answer, still read as "not a group" (nil, nil), and so still cacheable.
322	func TestNexusNonGroupStillReadsAsNotAGroup(t *testing.T) {
323		for _, body := range []string{
324			`{"type":"hosted","format":"docker"}`,
325			`{"type":"proxy","format":"docker"}`,
326		} {
327			t.Run(body, func(t *testing.T) {
328				var formatHits atomic.Int32
329				info, hits := nexusServer(t, func(w http.ResponseWriter, r *http.Request) {
330					if strings.Contains(r.URL.Path, "/group/") {
331						formatHits.Add(1)
332					}
333					_, _ = io.WriteString(w, body)
334				})
335	
336				members, err := (&NexusDetector{}).DetectGroup(context.Background(), info)
337	
338				if err != nil {
339					t.Fatalf("err = %v, want nil: a real non-group is an answer, not a failure", err)
340				}
341				if members != nil {
342					t.Errorf("members = %v, want nil", members)
343				}
344				if got := hits.Load(); got != 1 || formatHits.Load() != 0 {
345					t.Errorf("requests = %d (format endpoint %d), want 1 and 0", got, formatHits.Load())
346				}
347			})
348		}
349	}
