231	// 6. A 200 whose body is not a repository document is an error, never a "not a
232	// group": the caller caches the second and must not cache the first (D23), or a
233	// proxy login page would erase the members last known. No partial decoding: a
234	// document that fails halfway yields no members at all.
235	func TestNexusUnreadableReplyIsAnError(t *testing.T) {
236		var syntaxErr *json.SyntaxError
237		var typeErr *json.UnmarshalTypeError
238		cases := []struct {
239			name string
240			body string
241			// want is the sentinel the error must wrap, or nil.
242			want error
243			// as is a pointer to the json error type errors.As must find, or nil.
244			as any
245		}{
246			{"empty body", "", errEmptyReply, nil},
247			{"whitespace only", "  \n", errEmptyReply, nil},
248			{"truncated JSON", "{", nil, &syntaxErr},
249			{"HTML login page", "<html>login</html>", nil, &syntaxErr},
250			{"trailing garbage", `{"type":"group"} trailing`, nil, &syntaxErr},
251			{"group cut before its end", `{"type":"group","group":{"memberNames":["a-proxy"]} trailing`, nil, &syntaxErr},
252			{"type is not a string", `{"type":5}`, nil, &typeErr},
253			{"members are not a list", `{"type":"group","format":"docker","group":{"memberNames":5}}`, nil, &typeErr},
254			{"empty object", `{}`, errNoRepositoryType, nil},
255			{"null", `null`, errNoRepositoryType, nil},
256			{"object with no type", `{"format":"docker","group":{"memberNames":["a-proxy"]}}`, errNoRepositoryType, nil},
257		}
258		for _, tc := range cases {
259			t.Run(tc.name, func(t *testing.T) {
260				info, hits := nexusServer(t, func(w http.ResponseWriter, _ *http.Request) {
261					_, _ = io.WriteString(w, tc.body)
262				})
263	
264				members, err := (&NexusDetector{}).DetectGroup(context.Background(), info)
265	
266				if err == nil {
267					t.Fatalf("err = nil with members %v, want an error (an unreadable reply is not \"not a group\")", members)
268				}
269				if len(members) != 0 {
270					t.Errorf("members = %v, want none (no partial decoding)", members)
271				}
272				if tc.want != nil && !errors.Is(err, tc.want) {
273					t.Errorf("err = %v, want errors.Is %v", err, tc.want)
274				}
275				if tc.as != nil && !errors.As(err, tc.as) {
276					t.Errorf("err = %v (%T), want errors.As %T", err, err, tc.as)
277				}
278				var se *oci.StatusError
279				if errors.As(err, &se) {
280					t.Errorf("err = %v, is a *oci.StatusError, want a reading error (the status was 200)", err)
281				}
282				wantNoSecret(t, "error", err.Error())
283				if got := hits.Load(); got != 1 {
284					t.Errorf("the server received %d requests, want 1 (an unreadable reply stops the detection)", got)
285				}
286			})
287		}
288	}
